async updateRefs(cmds: RefCmd[], pushId: string): Promise<RefResult[]> {
  const missing = new Set<string>();
  await Promise.all(cmds.filter(c => c.new !== ZERO).map(async c => {
    const hit = (await this.env.BUCKET.head(`pending/${pushId}/${c.new}`))
             ?? (await this.env.BUCKET.head(`objects/${c.new}`));
    if (!hit) missing.add(c.new);
  }));
  const sql = this.ctx.storage.sql;
  return this.ctx.storage.transactionSync(() => {   // no await inside => no interleaving
    const now = Date.now(); const results: RefResult[] = [];
    for (const c of cmds) {
      if (missing.has(c.new)) { results.push({ name: c.name, ok: false, reason: "missing necessary objects" }); continue; }
      let written: number;
      if (c.old === ZERO)      written = sql.exec("INSERT OR IGNORE INTO refs (name, sha, updated_at) VALUES (?, ?, ?)", c.name, c.new, now).rowsWritten;
      else if (c.new === ZERO) written = sql.exec("DELETE FROM refs WHERE name = ? AND sha = ?", c.name, c.old).rowsWritten;
      else                     written = sql.exec("UPDATE refs SET sha = ?, updated_at = ? WHERE name = ? AND sha = ?", c.new, now, c.name, c.old).rowsWritten;
      results.push(written === 1 ? { name: c.name, ok: true } : { name: c.name, ok: false, reason: "fetch first" });
    }
    return results;
  });
}

