    match cmd.as_deref() {
        Some(b"ls-refs") => Ok(V2Command::LsRefs(parse_ls_refs(&args)?)),
        Some(b"fetch") => Ok(V2Command::Fetch(parse_fetch(&args)?)),
        _ => Err(Error::Protocol("unknown command".into())),   // object-info: not advertised (rule 6), not accepted
    }
