    for l in args { match l.as_slice() {
        b"symrefs" => a.symrefs = true, b"peel" => a.peel = true, b"unborn" => a.unborn = true,
        x => a.prefixes.push(x.strip_prefix(b"ref-prefix ").ok_or_else(|| bad("ls-refs", x))?.into()),
    } }
