      : this.ctx.storage.sql.exec("INSERT OR REPLACE INTO refs (name, sha) VALUES (?, ?)", c.ref, c.new);
    this.ctx.storage.sql.exec("DELETE FROM pending WHERE id = ?", pushId);
    return results;
  });
