    for part in [date.as_str(), "auto", "s3", "aws4_request"] { k = hmac(&k, part.as_bytes())?; }
    Ok(format!("https://{host}{path}?{qs}&X-Amz-Signature={}", hex::encode(hmac(&k, sts.as_bytes())?)))
}
