private async receivePack(req: Request): Promise<Response> {
  const { oldOid, newOid, ref } = parseCommandPktLines(req);   // "<old> <new> refs/heads/live/foo\0report-status-v2"
  if (!ref.startsWith("refs/heads/live/")) return classicCompareAndSwap(this.ctx, oldOid, newOid, ref);
  const branch = ref.slice("refs/heads/live/".length);
  const actor = req.headers.get("x-actor") ?? "anon", lamport = Date.now();
  const ops: Op[] = [];
  for (const d of await treeDiff(this.env.BUCKET, oldOid, newOid))      // pushed commit -> path-level CRDT ops
    ops.push({ actor, lamport, path: d.path, blob: d.newBlob, base: d.oldBlob ?? undefined });
  this.appendOps(branch, ops, newOid);                                    // INSERT OR IGNORE, PK (branch,actor,lamport,path)
  const tip = await this.materialize(branch);                             // LWW/diff3 merge -> tree objects -> n-parent commit in R2
  return pktLines([`unpack ok`, `ok ${ref}`, `option new-oid ${tip}`, `option forced-update`]); // report-status-v2
}

private async putObject(type: string, payload: Uint8Array): Promise<string> {
  const raw = concat(enc.encode(`${type} ${payload.byteLength}\0`), payload);
  const sha = hex(await crypto.subtle.digest("SHA-1", raw));
  await this.env.BUCKET.put(`objects/${sha}`, raw);
  return sha;
}

