    expect = parseTree(objs[i].body).find(e => e.name === segs[i - 1])!.oid;
  }
  if (objs.at(-1)!.oid !== expect) throw new Error("blob not linked");
  return objs.at(-1)!.body;                            // verified content of <path> at <trustedCommit>
