    const res = await stub.blame(arg("path"), arg("rev"));
    if (res === "pending") { await line("blame"); await line("status pending"); }
    else {
      const who = new Map((await stub.agents([...new Set(res.map(l => l.commit))])).map(a => [a.sha, a]));
      await line("blame");
