    let oid = |s: &str| ObjectId::from_hex(s.as_bytes()).map_err(|_| Error::Internal("bad oid from DO".into()));
    let refs = d.refs.iter().map(|r| Ok(RefRow { name: r.name.as_str().into(), target: oid(&r.target)?,
