    pub fn parse(path: &str) -> Result<(Self, String), Error> {
        let mut it = path.strip_prefix('/').ok_or(Error::NotFound)?.splitn(3, '/');
        let (owner, repo, rest) = (it.next().unwrap_or(""), it.next().unwrap_or(""), it.next().unwrap_or(""));
